using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        string jsonData = File.ReadAllText(dataPath);
        JArray data = JArray.Parse(jsonData);

        GameObject chartObj = new GameObject("ScienceScoreChart");
        Canvas canvas = chartObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        chartObj.AddComponent<UnityEngine.UI.CanvasScaler>();
        chartObj.AddComponent<UnityEngine.UI.GraphicRaycaster>();

        BarChart chart = chartObj.AddComponent<BarChart>();
        chart.GetOrAddChartComponent<Title>().text = "ScienceScoreChart";
        chart.GetOrAddChartComponent<Legend>();
        chart.GetOrAddChartComponent<XAxis>();
        chart.GetOrAddChartComponent<YAxis>();

        var serie = chart.AddSerie<Bar>("Science Score");
        serie.itemStyle.color = "#00FF00ff";

        foreach (var item in data)
        {
            string studentId = item["student_id"].ToString();
            float score = (float)item["science_score"];
            chart.AddXAxisData(studentId);
            chart.AddData(0, score);
        }

        chartObj.transform.position = new Vector3(0.00f, 1.70f, -2.00f);
        chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0.00f, 0.00f, -1.00f));
        chartObj.transform.localScale = new Vector3(0.01f, 0.01f, 0.01f);
    }
}

using UnityEngine;
using System.IO;
using Newtonsoft.Json.Linq;
using DxR;

public static class GeneratedCode
{
    public static void Execute()
    {
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/city/building_003.json");
        string jsonData = File.ReadAllText(dataPath);
        JArray data = JArray.Parse(jsonData);

        GameObject visObj = new GameObject("Building003GasUsageScatter");
        DxRVisBuilder builder = visObj.AddComponent<DxRVisBuilder>();

        builder.SetMarkType("point");
        builder.SetDataSource(dataPath);

        builder.AddChannel("x", "time", "nominal");
        builder.AddChannel("y", "gas", "quantitative");
        builder.AddChannel("z", "electricity", "quantitative");
        builder.AddChannel("color", "gas", "quantitative", "#00FFFFFF");
        builder.AddChannel("size", "gas", "quantitative");

        builder.SetTitle("Building 003 Gas Usage");

        visObj.transform.position = new Vector3(0.00f, 3.50f, 0.00f);
        visObj.transform.rotation = Quaternion.LookRotation(new Vector3(0.00f, 0.00f, -1.00f));
        visObj.transform.localScale = new Vector3(2.00f, 2.00f, 2.00f);

        builder.BuildVisualization();
    }
}

