using UnityEngine;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        GameObject chartObj = GameObject.Find("MathScoreChart");
        if (chartObj == null) return;

        BaseChart chart = chartObj.GetComponent<BaseChart>();
        if (chart == null) return;

        int index = -1;
        for (int i = 0; i < chart.GetXAxis(0).data.Count; i++)
        {
            if (chart.GetXAxis(0).data[i] == "S006")
            {
                index = i;
                break;
            }
        }

        if (index >= 0)
        {
            chart.RemoveData(0, index);
        }
    }
}
